import { SECTION_REGISTRY, SECTION_GROUPS } from "@/content/sections";

/*
 * Builds the manifest payload straight from SECTION_REGISTRY — the same
 * source every section wrapper already reads its fields from — rather
 * than from the checked-in content-schema.json. That file is a
 * human-reviewable snapshot (regenerated by `npm run schema:export`),
 * but a snapshot can go stale the moment someone edits a section file
 * and forgets to re-run the script, exactly what happened to Location's
 * fields here. Building it at push time from the registry itself makes
 * that whole class of drift impossible.
 *
 * A section with no fields (sitemap: generated from real data, not
 * edited) isn't part of the manifest at all — there is nothing to
 * declare, and the panel's own schema requires at least one field per
 * section.
 */
function buildManifestPayload() {
  const sections = Object.entries(SECTION_REGISTRY)
    .filter(([, config]) => config.fields.length > 0)
    .map(([slug, config]) => ({
      slug,
      label: config.label,
      group: config.group,
      minRole: config.minRole,
      fields: config.fields.map((field) => ({
        key: field.key,
        label: field.label,
        type: field.type,
        ...(field.long ? { multiline: true } : {}),
        ...(field.helperText ? { helperText: field.helperText } : {}),
        /*
         * A section file's own defaultValue is always a plain string
         * (matching ContentField.value being a text column, and every
         * section's own defaultValue convention), but the panel's
         * manifest schema requires a BOOLEAN field's default to be a
         * real true/false, not the string "true"/"false" — coerced
         * here rather than changing the site-wide convention. Never sent
         * for LIST: the panel's schema forbids a LIST field declaring one.
         */
        ...(field.defaultValue != null
          ? {
              default:
                field.type === "BOOLEAN"
                  ? field.defaultValue === "true"
                  : field.defaultValue,
            }
          : {}),
        /*
         * A LIST field's per-item shape (e.g. Project Gallery's slides:
         * image, alt, heading, caption). Mapped the same way as a normal
         * field, one level down — the panel's schema mirrors this
         * exactly (ItemFieldSchema).
         */
        ...(field.itemLabel ? { itemLabel: field.itemLabel } : {}),
        ...(field.itemFields
          ? {
              itemFields: field.itemFields.map((itemField) => ({
                key: itemField.key,
                label: itemField.label,
                type: itemField.type,
                ...(itemField.long ? { multiline: true } : {}),
                ...(itemField.helperText
                  ? { helperText: itemField.helperText }
                  : {}),
                ...(itemField.defaultValue != null
                  ? {
                      default:
                        itemField.type === "BOOLEAN"
                          ? itemField.defaultValue === "true"
                          : itemField.defaultValue,
                    }
                  : {}),
              })),
            }
          : {}),
      })),
    }));

  return { groups: SECTION_GROUPS, sections };
}

/*
 * Pushes the current manifest to the central admin panel, called once
 * from instrumentation.js on every server boot — a deploy is what keeps
 * the panel's picture of this site's sections current.
 *
 * Fails open, same principle as getSectionContent's own fallback to
 * defaults: the site must never fail to start, or fail a real request,
 * because the panel happens to be unreachable at boot. A push failure
 * is logged and otherwise swallowed; the panel simply keeps showing
 * whatever it last successfully received until the next boot succeeds.
 */
const REQUEST_TIMEOUT_MS = 8000;

export async function pushManifestToPanel() {
  const apiUrl = process.env.CONTENT_API_URL;
  const apiToken = process.env.CONTENT_API_TOKEN;

  if (!apiUrl || !apiToken) {
    return;
  }

  try {
    const response = await fetch(`${apiUrl}/api/v1/manifest`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${apiToken}`,
      },
      body: JSON.stringify(buildManifestPayload()),
      /*
       * Without this, "fails open" only covered errors — and a hang is not an
       * error. Node's fetch has no default request timeout, so a panel that
       * accepted the connection and then went quiet left this awaiting
       * forever. Reproduced against a socket that accepts and never replies:
       * the server logged "Ready" and then refused every request for 45s+,
       * because instrumentation.js was still awaiting this call. Render reads
       * that as an unhealthy instance and restarts it, on a loop.
       */
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) {
      /*
       * Status and statusText only. Everywhere else in this codebase avoids
       * logging a remote service's response body, because a misconfigured
       * endpoint can echo the request back — and this request carries the
       * API token in a header.
       */
      console.error(
        "Manifest push failed:",
        response.status,
        response.statusText,
      );
      return;
    }

    const result = await response.json();
    console.log(`Manifest pushed to panel: version ${result.version}`);
  } catch (error) {
    console.error("Manifest push failed:", error?.message);
  }
}
